<?php $editing=!empty($user);$title=$editing?'Edit User':'Add User';require __DIR__.'/../layouts/header.php';$action=$editing?route('admin.user.edit',['id'=>$user['id']]):route('admin.users');?><div class="pagehead"><h1><?=$title?></h1></div><form class="panel form" method="post" action="<?=$action?>"><?=csrf_field()?><div class="form-grid"><label>Full name<input name="full_name" required value="<?=e($user['full_name']??'')?>"></label><label>Username<input name="username" required value="<?=e($user['username']??'')?>"></label><label>Email<input type="email" name="email" value="<?=e($user['email']??'')?>"></label><label>Password<input type="password" name="password" <?=$editing?'':'required'?>></label><label>Role<select name="role_id"><?php foreach($roles as $role):?><option value="<?=$role['id']?>" <?=((int)($user['role_id']??0)===$role['id']?'selected':'')?>><?=e($role['role_name'])?></option><?php endforeach;?></select></label><label>Designation<input name="designation" value="<?=e($user['designation']??'')?>"></label><label>Phone<input name="phone" value="<?=e($user['phone']??'')?>"></label><label><input type="checkbox" name="is_active" value="1" <?=!isset($user)||!empty($user['is_active'])?'checked':''?>> Active</label><label><input type="checkbox" name="is_banned" value="1" <?=!empty($user['is_banned'])?'checked':''?>> Banned</label></div><button class="primary"><?=$editing?'Update User':'Create User'?></button></form><?php require __DIR__.'/../layouts/footer.php';?>
